package com.clrg.core.audio

import kotlin.math.PI
import kotlin.math.exp
import kotlin.math.pow
import kotlin.math.sin

/** Instruments of the built-in synthesiser. All sound in the game is generated by this code (no audio assets). */
enum class Instrument { BELL, LEAD, PLUCK, BASS, PAD, KICK, SNARE, HAT, CLAP, SLEIGH, GLOCK }

fun midiToHz(m: Float): Float = (440.0 * 2.0.pow((m - 69.0) / 12.0)).toFloat()

private const val TWO_PI = TAU

/**
 * One playing note. Voices live in a fixed pool and keep their buffers between notes, so the audio thread does not
 * allocate while running.
 */
class Voice {
    var active = false
    var inst = Instrument.BELL
    var freq = 440f
    var vel = 1f
    var t = 0f           // seconds since note on
    var dur = 0.2f       // note length (gate) in seconds
    var pan = 0f
    var startDelay = 0   // samples to wait before starting (sample-accurate onsets)
    private var phase = 0f
    private var phase2 = 0f
    private var lp = 0f
    private var noise = 22222
    private val ks = FloatArray(2400)
    private var ksLen = 0
    private var ksPos = 0

    fun start(inst: Instrument, freq: Float, vel: Float, dur: Float, pan: Float, delay: Int, sr: Int) {
        this.inst = inst; this.freq = freq; this.vel = vel; this.dur = dur; this.pan = pan
        startDelay = delay; t = 0f; phase = 0f; phase2 = 0f; lp = 0f; active = true
        if (inst == Instrument.PLUCK) {
            ksLen = (sr / freq).toInt().coerceIn(2, ks.size)
            for (i in 0 until ksLen) ks[i] = nextNoise()
            ksPos = 0
        }
    }

    private fun nextNoise(): Float {
        noise = noise * 1103515245 + 12345
        return ((noise ushr 9) and 0xFFFF) / 32768f - 1f
    }

    private fun adsr(a: Float, d: Float, s: Float, r: Float): Float {
        val env = when {
            t < a -> t / a
            t < a + d -> 1f - (1f - s) * (t - a) / d
            else -> s
        }
        return if (t <= dur) env else env * exp(-(t - dur) / r)
    }

    /** Returns the next mono sample (or 0 while waiting); deactivates itself when finished. */
    fun next(sr: Int): Float {
        if (startDelay > 0) { startDelay--; return 0f }
        val dt = 1f / sr
        val out: Float
        when (inst) {
            Instrument.BELL -> {
                val idx = 2.2f * exp(-t * 5f)
                phase2 += TWO_PI * freq * 3.5f * dt
                phase += TWO_PI * freq * dt
                val env = minOf(1f, t / 0.003f) * exp(-t * 2.8f)
                out = sin(phase + idx * sin(phase2)) * env * 0.5f
                if (t > 2.5f) active = false
            }
            Instrument.GLOCK -> {
                phase += TWO_PI * freq * dt
                val env = minOf(1f, t / 0.002f) * exp(-t * 5f)
                out = (sin(phase) + 0.25f * sin(phase * 4f) * exp(-t * 20f)) * env * 0.45f
                if (t > 1.5f) active = false
            }
            Instrument.LEAD -> {
                val vib = if (t > 0.15f) 1f + 0.004f * sin(TWO_PI * 5.5f * t) else 1f
                phase += freq * vib * dt
                if (phase >= 1f) phase -= 1f
                val sq = if (phase < 0.3f) 1f else -1f
                lp += 0.18f * (sq - lp)
                val env = adsr(0.008f, 0.12f, 0.65f, 0.07f)
                out = lp * env * 0.22f
                if (t > dur + 0.5f) active = false
            }
            Instrument.PLUCK -> {
                val i0 = ksPos
                val i1 = (ksPos + 1) % ksLen
                val v = 0.5f * (ks[i0] + ks[i1]) * 0.994f
                ks[i0] = v
                ksPos = i1
                val env = if (t <= dur) 1f else exp(-(t - dur) / 0.08f)
                out = v * env * 0.5f
                if (t > dur + 0.4f || t > 2f) active = false
            }
            Instrument.BASS -> {
                phase += freq * dt
                if (phase >= 1f) phase -= 1f
                val tri = 4f * kotlin.math.abs(phase - 0.5f) - 1f
                phase2 += TWO_PI * freq * dt
                val env = adsr(0.005f, 0.08f, 0.8f, 0.06f)
                out = (tri * 0.6f + sin(phase2) * 0.5f) * env * 0.42f
                if (t > dur + 0.4f) active = false
            }
            Instrument.PAD -> {
                phase += freq * dt; if (phase >= 1f) phase -= 1f
                phase2 += freq * 1.006f * dt; if (phase2 >= 1f) phase2 -= 1f
                val a = 4f * kotlin.math.abs(phase - 0.5f) - 1f
                val b = 4f * kotlin.math.abs(phase2 - 0.5f) - 1f
                val env = adsr(0.35f, 0.3f, 0.8f, 0.6f)
                out = (a + b) * env * 0.12f
                if (t > dur + 3f) active = false
            }
            Instrument.KICK -> {
                val f = 45f + 85f * exp(-t * 28f)
                phase += TWO_PI * f * dt
                out = sin(phase) * exp(-t * 9f) * 0.9f
                if (t > 0.4f) active = false
            }
            Instrument.SNARE -> {
                phase += TWO_PI * 190f * dt
                val n = nextNoise()
                val hp = n - lp; lp = n
                out = (hp * 0.5f * exp(-t * 18f) + sin(phase) * 0.35f * exp(-t * 30f)) * 0.7f
                if (t > 0.3f) active = false
            }
            Instrument.HAT -> {
                val n = nextNoise()
                val hp = n - lp; lp = n
                out = hp * exp(-t * 70f) * 0.22f
                if (t > 0.1f) active = false
            }
            Instrument.CLAP -> {
                val n = nextNoise()
                val burst = if (t < 0.035f) (if (((t * 330).toInt() and 1) == 0) 1f else 0.25f) else exp(-(t - 0.035f) * 25f)
                val hp = n - lp; lp = n * 0.5f
                out = hp * burst * 0.35f
                if (t > 0.25f) active = false
            }
            Instrument.SLEIGH -> {
                val am = 0.6f + 0.4f * sin(TWO_PI * 37f * t)
                val s = sin(TWO_PI * 2950f * t) + 0.8f * sin(TWO_PI * 4130f * t) + 0.6f * sin(TWO_PI * 5370f * t) + 0.4f * sin(TWO_PI * 6710f * t)
                out = (s * 0.18f + nextNoise() * 0.12f) * am * exp(-t * 26f) * 0.5f
                if (t > 0.25f) active = false
            }
        }
        t += dt
        return out * vel
    }
}
